// MeshGuard node certificate ("pass") verification for the browser gateway.
// Mirrors src/identity/org.zig; tests/fixtures/passes.json, generated by the Zig
// implementation (`zig build pass-fixtures`), keeps the two in agreement.
import { createPublicKey, verify } from 'node:crypto';

export const CERT_V1_SIZE = 186;
export const CERT_SIZE = 314;
const SIGNED_V1 = 114;
const FLAG_DELEGATED = 1;
const SPKI = Buffer.from('302a300506032b6570032100', 'hex');
const zero = bytes => bytes.every(b => b === 0);
const equal = (a, b) => a.length === b.length && a.every((byte, i) => byte === b[i]);

function edVerify(publicKey, message, signature) {
  try {
    const key = createPublicKey({ key: Buffer.concat([SPKI, Buffer.from(publicKey)]), format: 'der', type: 'spki' });
    return verify(null, Buffer.from(message), key, Buffer.from(signature));
  } catch { return false; }
}

/** Parses a 186- or 314-byte certificate; v1 certificates are zero-padded. */
export function parsePass(bytes) {
  if (!(bytes instanceof Uint8Array) || (bytes.length !== CERT_V1_SIZE && bytes.length !== CERT_SIZE)) return null;
  const wire = new Uint8Array(CERT_SIZE); wire.set(bytes);
  const view = new DataView(wire.buffer);
  const version = wire[0];
  return {
    wire, version,
    orgPublicKey: wire.slice(1, 33), publicKey: wire.slice(33, 65),
    issuedAt: Number(view.getBigInt64(97, true)), expiresAt: Number(view.getBigInt64(105, true)),
    flags: wire[113], signature: wire.slice(114, 178),
    wgPublicKey: version === 2 ? wire.slice(186, 218) : null,
    issuerPublicKey: version === 2 ? wire.slice(218, 250) : null,
    delegationSignature: version === 2 ? wire.slice(250, 314) : null,
  };
}

function signedPayload(pass) {
  const v1 = pass.wire.subarray(0, SIGNED_V1);
  if (pass.version === 1) return v1;
  const out = new Uint8Array(SIGNED_V1 + 64);
  out.set(v1); out.set(pass.wgPublicKey, SIGNED_V1); out.set(pass.issuerPublicKey, SIGNED_V1 + 32);
  return out;
}

function delegationPayload(pass) {
  const out = new Uint8Array(1 + 32 + 32 + 8 + 1);
  out[0] = pass.version; out.set(pass.orgPublicKey, 1); out.set(pass.issuerPublicKey, 33);
  new DataView(out.buffer).setBigInt64(65, BigInt(pass.expiresAt), true);
  out[73] = pass.flags;
  return out;
}

/** True when the signature (and any delegation grant) is valid; no time or trust checks. */
export function passSignatureValid(pass) {
  if (pass.version === 1) return edVerify(pass.orgPublicKey, signedPayload(pass), pass.signature);
  if (pass.version !== 2 || zero(pass.wgPublicKey)) return false;
  if (pass.flags & FLAG_DELEGATED) {
    if (zero(pass.issuerPublicKey)) return false;
    return edVerify(pass.issuerPublicKey, signedPayload(pass), pass.signature)
      && edVerify(pass.orgPublicKey, delegationPayload(pass), pass.delegationSignature);
  }
  return edVerify(pass.orgPublicKey, signedPayload(pass), pass.signature);
}

/** Valid at `now` (seconds) within `skew` seconds of clock difference, as `isValidAt`. */
export function passTimeValid(pass, now, skew) {
  if (pass.version !== 1 && pass.version !== 2) return false;
  if (pass.issuedAt > now + skew) return false;
  return pass.expiresAt === 0 || now < pass.expiresAt + skew;
}

/**
 * Checks a pass for a session: issued by one of `trustedOrgs` (Base64 keys) to
 * exactly this Ed25519 key and, for v2, this WireGuard key; correctly signed;
 * valid now. Returns `{ expiresAt }` (0 = never) or a reason string.
 */
export function verifyPass(bytes, { publicKey, wgPublicKey, trustedOrgs, now = Math.floor(Date.now() / 1000), skew = 300 }) {
  const pass = parsePass(bytes);
  if (!pass) return 'malformed';
  if (!trustedOrgs.has(Buffer.from(pass.orgPublicKey).toString('base64'))) return 'untrusted-org';
  if (!equal(pass.publicKey, publicKey)) return 'wrong-identity';
  if (pass.version === 2 && !equal(pass.wgPublicKey, wgPublicKey)) return 'wrong-wireguard-key';
  if (!passTimeValid(pass, now, skew)) return 'expired';
  if (!passSignatureValid(pass)) return 'bad-signature';
  return { expiresAt: pass.expiresAt, wire: pass.wire };
}
